#include <stdio.h>

#define MAXN 1000

/* Super-legal <=> condição de Monge (todos os quadrados 2x2 adjacentes:
   A[i][j] + A[i+1][j+1] <= A[i][j+1] + A[i+1][j]).
   Marcamos cada célula de B (L-1 x C-1) onde essa condição falha e achamos
   o maior retângulo só de células "boas"; a submatriz correspondente em A
   tem (h+1)*(w+1) elementos. Se nenhuma célula for válida, a resposta é 0. */

static int rprev[MAXN], rcur[MAXN];
static int hgt[MAXN];
static int lo[MAXN], hi[MAXN];
static int stk[MAXN];

static char ibuf[1 << 20];
static int ilen = 0, ipos = 0;

static int gc(void) {
    if (ipos == ilen) {
        ilen = (int)fread(ibuf, 1, sizeof(ibuf), stdin);
        ipos = 0;
        if (ilen <= 0) return -1;
    }
    return (unsigned char)ibuf[ipos++];
}

static int readInt(void) {
    int c, sgn = 1, x = 0;
    for (;;) {
        c = gc();
        if (c == -1 || c == '-' || (c >= '0' && c <= '9')) break;
    }
    if (c == '-') { sgn = -1; c = gc(); }
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = gc(); }
    return x * sgn;
}

int main(void) {
    int L = readInt(), C = readInt();
    int n = C - 1;                 /* colunas da matriz de violações */
    int *prev = rprev, *cur = rcur;
    int best = 0;
    int i, j, top;

    for (j = 0; j < C; j++) prev[j] = readInt();

    for (i = 1; i < L; i++) {
        for (j = 0; j < C; j++) cur[j] = readInt();

        /* atualiza alturas: nº de linhas de B consecutivas "boas" terminando aqui */
        for (j = 0; j < n; j++) {
            int b = prev[j] + cur[j + 1] - prev[j + 1] - cur[j];
            hgt[j] = (b <= 0) ? hgt[j] + 1 : 0;
        }

        /* anterior estritamente menor */
        top = 0;
        for (j = 0; j < n; j++) {
            while (top > 0 && hgt[stk[top - 1]] >= hgt[j]) top--;
            lo[j] = (top > 0) ? stk[top - 1] : -1;
            stk[top++] = j;
        }

        /* próximo estritamente menor */
        top = 0;
        for (j = n - 1; j >= 0; j--) {
            while (top > 0 && hgt[stk[top - 1]] >= hgt[j]) top--;
            hi[j] = (top > 0) ? stk[top - 1] : n;
            stk[top++] = j;
        }

        /* candidatos: retângulo de altura hgt[j] e largura máxima */
        for (j = 0; j < n; j++) {
            if (hgt[j] > 0) {
                int w = hi[j] - lo[j] - 1;
                int v = (hgt[j] + 1) * (w + 1);
                if (v > best) best = v;
            }
        }

        { int *t = prev; prev = cur; cur = t; }
    }

    printf("%d\n", best);
    return 0;
}
